    id text NOT NULL,
    "userId" text NOT NULL,
    "comicId" text NOT NULL,
    body text NOT NULL,
    "helpfulCount" integer DEFAULT 0 NOT NULL,
    "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) without time zone NOT NULL,
    "deletedAt" timestamp(3) without time zone
);


--
-- Name: ReviewVote; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."ReviewVote" (
    "userId" text NOT NULL,
    "reviewId" text NOT NULL
);


--
-- Name: Role; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."Role" (
    id text NOT NULL,
    name text NOT NULL
);


--
-- Name: Session; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."Session" (
    id text NOT NULL,
    "tokenHash" text NOT NULL,
    "userId" text NOT NULL,
    "userAgent" text,
    "expiresAt" timestamp(3) without time zone NOT NULL,
    "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: SourceChapter; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."SourceChapter" (
    id text NOT NULL,
    "sourceTitleId" text NOT NULL,
    "chapterId" text NOT NULL,
    "externalId" text NOT NULL,
    "numberLabel" text,
    title text,
    volume text,
    "sourceUrl" text NOT NULL,
    language text,
    "publishedAt" timestamp(3) without time zone,
    "pageCount" integer,
    groups text[] DEFAULT ARRAY[]::text[] NOT NULL
);


--
-- Name: SourceSetting; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."SourceSetting" (
    "sourceId" text NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    "displayName" text,
    "updatedAt" timestamp(3) without time zone NOT NULL
);


--
-- Name: SourceTitle; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."SourceTitle" (
    id text NOT NULL,
    "sourceId" text NOT NULL,
    "externalId" text NOT NULL,
    title text NOT NULL,
    "sourceUrl" text NOT NULL,
    "coverUrl" text,
    "contentType" text NOT NULL,
    state public."SourceTitleState" NOT NULL,
    "comicId" text,
    "reviewedById" text,
    "reviewedAt" timestamp(3) without time zone,
    "reviewNote" text,
    "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) without time zone NOT NULL
);


--
-- Name: Subscription; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."Subscription" (
    id text NOT NULL,
    "userId" text NOT NULL,
    "planId" text NOT NULL,
    status public."SubscriptionStatus" DEFAULT 'ACTIVE'::public."SubscriptionStatus" NOT NULL,
    "currentPeriodEnd" timestamp(3) without time zone NOT NULL,
    "providerRef" text,
    "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: SubscriptionPlan; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."SubscriptionPlan" (
    id text NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    "priceMinor" integer NOT NULL,
    currency text DEFAULT 'INR'::text NOT NULL,
    "intervalMonths" integer NOT NULL,
    active boolean DEFAULT true NOT NULL
);


--
-- Name: User; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."User" (
    id text NOT NULL,
    username text NOT NULL,
    email text NOT NULL,
    "passwordHash" text NOT NULL,
    "emailVerifiedAt" timestamp(3) without time zone,
    status public."UserStatus" DEFAULT 'ACTIVE'::public."UserStatus" NOT NULL,
    "roleId" text NOT NULL,
    "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp(3) without time zone NOT NULL,
    "deletedAt" timestamp(3) without time zone
);


--
-- Name: UserProfile; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."UserProfile" (
    "userId" text NOT NULL,
    "avatarUrl" text,
    bio text,
    "readingPrefs" jsonb,
    "notifyPrefs" jsonb
);


--
-- Name: _PermissionToRole; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public."_PermissionToRole" (
